Framescript.script:
//this.gotoAndStop(6);
this.stop();
createjs.Touch.enable(stage);
stage.mouseChildren = true;
var root = this;


root.title_animation.start_btn.cursor = "pointer";
root.title_animation.start_btn.removeAllEventListeners("click");
root.title_animation.start_btn.addEventListener("click", startGameF);

function startGameF() {
console.log("start")
	createjs.Sound.play("ClickSound");

	// 👇 ألغي الاهتزاز المجدول لو الطفل دوس قبل الـ 5 ثواني
	if (root._startBtnShakeTimer) {
		clearInterval(root._startBtnShakeTimer);
		root._startBtnShakeTimer = null;
	}

	let nextFrame = root.currentFrame + 1;

	root.gotoAndStop("d_intro");
}

if (root._startBtnShakeTimer) {
	clearInterval(root._startBtnShakeTimer);
}
root._startBtnShakeTimer = setInterval(function () {
	shake(root.title_animation.start_btn);
}, 5000);

this.stop();
var root = this;
isFirstLoad = true;

// 👇 الفريم ده هو فريم تهيئة اللعبة (مرة واحدة بس) وفي نفس الوقت فريم محتوى Q1 —
// لو السؤال اللي محتواه Q1 وقع في ترتيب عشوائي متأخر، هنرجع نزور الفريم ده تاني
// في نص الجلسة، فلازم نفرّق بين "أول مرة فعلاً" و"بس جاي أعرض محتوى Q1 دلوقتي"
// (حطيتها هنا فوق قوي عشان أي كود تحت يقدر يستخدمها، خصوصًا حاجات زي السكور
// اللي لازم تتصفّر مرة واحدة بس، مش في كل رجعة لمحتوى Q1)
var isFirstGameStart = !root.gameStarted;
root.gameStarted = true;

if (isFirstGameStart) {
	window.score = 0;
	window.completedCount = 0;
}

if (typeof musicEnabled === "undefined") {
	musicEnabled = true;
}

if (bgMusicInstance) {
	bgMusicInstance.paused = !musicEnabled;
}

/* =================================================
  Sounds
================================================= */
startBgMusic();
if (musicEnabled) {
	root.music_btn.gotoAndStop(0);
} else {
	root.music_btn.gotoAndStop(1);
}
root.music_btn.removeAllEventListeners();
root.music_btn.addEventListener("click", muteMusic);
function muteMusic() {
	createjs.Sound.play("ClickSound", {
		volume: 0.2
	});
	toggleMusic();
	if (musicEnabled) {
		root.music_btn.gotoAndStop(0);
	} else {
		root.music_btn.gotoAndStop(1);
	}
}


// ========================================
// Question Sound Toggle
// ========================================

var questionSoundInstance = null;

root.question_sound_btn.removeAllEventListeners("click");
root.question_sound_btn.on("click", questionSound);

// 👇 كل سؤال ليه صوت "tap each ..." مختلف حسب العنصر اللي بيتعد فيه
var questionTapSounds = {
	1: "tap_each_book",
	2: "tap_each_pencil",
	3: "tap_each_bag",
	4: "tap_each_ruler",
	5: "tap_each_eraser"
};

function questionSound() {
	var soundId = questionTapSounds[window.currentQuestionNumber] || "count_and_color";
	playVoice(soundId);
}

// 👇 كل سؤال ليه صوت "choose the correct number of ..." مختلف، بيتقال في فريم الاختيارات (ch_1)
var questionChooseSounds = {
	1: "choose_the_correct_number_of_books",
	2: "choose_the_correct_number_of_pencils",
	3: "choose_the_correct_number_of_bags",
	4: "choose_the_correct_number_of_rulers",
	5: "choose_the_correct_number_of_erasers"
};

function chooseSound() {
	var soundId = questionChooseSounds[window.currentQuestionNumber];
	if (!soundId) {
		return;
	}
	playVoice(soundId);
}

// مرجع واحد لكل أصوات الشرح والأرقام — أي صوت جديد يقطع اللي قبله
var currentVoiceInstance = null;

function playVoice(soundId) {
	if (currentVoiceInstance) {
		currentVoiceInstance.stop();
		currentVoiceInstance = null;
	}
	// 👇 اقطع صوت النجاح/الغلط لو شغال، عشان محصلش تداخل مع صوت العنوان/الأرقام
	if (window.currentSuccessVoiceInstance) {
		window.currentSuccessVoiceInstance.stop();
		window.currentSuccessVoiceInstance = null;
	}
	if (window.currentErrorVoiceInstance) {
		window.currentErrorVoiceInstance.stop();
		window.currentErrorVoiceInstance = null;
	}
	currentVoiceInstance = createjs.Sound.play(soundId);
	window.currentVoiceInstance = currentVoiceInstance;   // 👈 متاح عشان صوت النجاح/الغلط يقدر يقطعه لو شغال
	window.soundInstances[soundId] = currentVoiceInstance;
	return currentVoiceInstance;
}

/* =================================================
   Overly background
================================================= */
if (isFirstGameStart) {
	root.overly.visible = true;
	root.overly.overly_animation.gotoAndPlay(0);
	root.input_blocker.visible = true;
	root.close_overly.visible = true;
	startCloseBtnShake(true);   // 👈 أول مرة في بداية النشاط = تقفل لوحدها بعد دورتين
}

// ========================================
// Pointer Hand
// ========================================

// Pointer
root.pointerTimer = null;

if (root.pointer) {
	//root.pointer.gotoAndStop(0);
	root.pointer.visible = false;
}

/* =========================================
   CLOSE OVERLAY WHEN CLICK OUTSIDE
========================================= */
// 👇 لو رجعنا الفريم ده بس عشان نعرض محتوى Q1 (مش بداية جلسة فعلية)، متفتحوش تاني —
// Animate نفسه بيرجّع يفعّل input_blocker (الـ_off tween بتاعه مربوط بمكان الفريم ده
// تحديدًا) بغض النظر عن السكريبت بتاعنا، فلازم نأكد إنه مقفول صراحة في الحالة دي
root.input_blocker.visible = isFirstGameStart;

root.close_overly.removeAllEventListeners("click");
root.close_overly.addEventListener("click", function () {
	closeOverlyF(null);   // 👈 null = تخطى فحص الحدود واقفل على طول
})
root.input_blocker.removeAllEventListeners();
root.input_blocker.addEventListener("click", closeOverlyF);

var firstOverlayClose = isFirstGameStart;   // 👈 يتصفّر بس أول بداية جلسة فعلية، مش كل رجعة للفريم ده
// silent = قفل تلقائي من غير صوت الضغطة
function closeOverlyF(event, silent) {
	console.log("🎲 [DEBUG] closeOverlyF — root.currentFrame:", root.currentFrame, "| currentQuestionNumber:", window.currentQuestionNumber, "| progressValue قبل:", root.progressValue, "| score:", window.score);

	// 👇 لو الضغطة جوه حدود block_overly (جوه overly)، متقفلش — أي حتة تانية تقفل
	if (event && root.overly.visible) {
		var blocker = root.overly.block_overly;
		if (blocker) {
			var localPoint = blocker.globalToLocal(event.stageX, event.stageY);
			var bounds = blocker.nominalBounds || blocker.getBounds();

			if (bounds &&
				localPoint.x >= bounds.x &&
				localPoint.x <= bounds.x + bounds.width &&
				localPoint.y >= bounds.y &&
				localPoint.y <= bounds.y + bounds.height) {
				return;
			}
		}
	}

	// اقطع كل الأصوات الشغالة (أصوات التايملاين + الفويس)
	window.stopAllActivitySounds();
	if (!silent) {
		createjs.Sound.play("ClickSound");
	}

	root.overly.visible = false;
	root.overly.overly_animation.gotoAndStop(0);
	root.input_blocker.visible = false;
	root.close_overly.visible = false;

	// stop only these specific sounds
	["count_and_color", "color", "count", "one", "confirm", "tap_each_book", "tap_each_pencil", "tap_each_bag", "tap_each_ruler", "tap_each_eraser"].forEach(function (id) {
		var inst = window.soundInstances[id];
		if (inst) {
			inst.stop();
			delete window.soundInstances[id];
		}
	});

	// 🔊 صوت السؤال (tap each ...) — أول إغلاق فقط، بس للسؤال الأول (باقي الأسئلة بتشغّله لوحدها أول ما تدخلها)
			if (firstOverlayClose) {
		firstOverlayClose = false;
		questionSound();
	}
	window.overlayShownBefore = true;   // 👈 المرات الجاية من غير صوت

	// 👇 ابدأ/جدد تكرار الـ hint
	if (root.scheduleHint) {
		root.scheduleHint();
	}

	// 👇 العد (counting_N) كان مستني الـoverly يتقفل عشان يشتغل — بلّغه دلوقتي
	if (root.onOverlyClosedForCounting) {
		root.onOverlyClosedForCounting();
	}

		stopCloseBtnShake();
}

root.show_overly.removeAllEventListeners("click");
root.show_overly.addEventListener("click", showOverlyF);
function showOverlyF() {

	createjs.Sound.play("ClickSound");

	// إلغاء Timer لو موجود
	if (root.pointerTimer) {
		clearTimeout(root.pointerTimer);
		root.pointerTimer = null;
	}

		// ❌ كان: if (!root.pointerShown && root.pointer) {
	// ✅ خليه:
	if (root.pointer) {
		//root.pointer.gotoAndStop(0);
		root.pointer.visible = false;
	}
	root.stopCountingHint();   // اقطع الـ hint لو شغال وقت فتح الـ overlay

	root.overly.visible = true;
	root.overly.overly_animation.gotoAndPlay(0);
	root.input_blocker.visible = true;
	root.close_overly.visible = true;

	root.setChildIndex(root.input_blocker, root.numChildren - 1);
	root.setChildIndex(root.overly, root.numChildren - 1);
	root.setChildIndex(root.close_overly, root.numChildren - 1);

		startCloseBtnShake();
}

// autoClose = بعد دورتين تقفل لوحدها بدل ما زرار الـ close يهتز
function startCloseBtnShake(autoClose) {
	stopCloseBtnShake();

	window.overlayShownBefore = false;   // 👈 فتحة جديدة = الصوت يشتغل تاني
	var loops = 0;

	window.onOverlayLoopEnd = function () {
		loops += 1;

		window.overlayShownBefore = true;   // بعد أول دورة، سكوت

		if (loops < 2) {
			return;
		}

		window.onOverlayLoopEnd = null;

		// 👇 أول فتحة في بداية النشاط: اقفلها لوحدها بعد دورتين
		if (autoClose) {
			if (root.overly.visible) {
				closeOverlyF(null, true);
			}
			return;
		}

		if (root.overly.visible) {
			shake(root.close_overly);
		}

		root._closeBtnShakeInterval = setInterval(function () {
			if (root.overly.visible) {
				shake(root.close_overly);
			}
		}, 5000);
	};
}

function stopCloseBtnShake() {
	window.onOverlayLoopEnd = null;
	if (root._closeBtnShakeTimer) {
		clearTimeout(root._closeBtnShakeTimer);
		root._closeBtnShakeTimer = null;
	}
	if (root._closeBtnShakeInterval) {
		clearInterval(root._closeBtnShakeInterval);
		root._closeBtnShakeInterval = null;
	}
}

var userInteracted = false;

// ========================================
// ترتيب الأسئلة العشوائي (randomized questions)
// ========================================
// 👇 الأسئلة (counting_N / count_ch_frame_qN / text_qN...) كل واحد منهم مربوط بفريم معيّن
// من فريمات المشهد بالأصل في الأنيميت — فبدل ما نحاول نبدّل المحتوى جوه فريم ثابت،
// بنعمل shuffle لأرقام الفريمات نفسها (1-5) ونتنقل ("gotoAndStop") للفريم الصح مباشرة
// في كل مرة — كده كل حاجة مرتبطة بالفريم (تيمة، نص، عدد ورد...) بتيجي صح تلقائيًا
// من غير أي تدخّل إضافي، لأننا فعليًا واقفين على الفريم الأصلي بتاعها.
var RESULTS_FRAME = 6;
root.generateQuestionOrder = function generateQuestionOrder() {
	var order = [1, 2, 3, 4, 5];
	for (var i = order.length - 1; i > 0; i -= 1) {
		var j = Math.floor(Math.random() * (i + 1));
		var tmp = order[i];
		order[i] = order[j];
		order[j] = tmp;
	}
	root.questionOrder = order;
	root.questionOrderIndex = 0;
};

// 👇 بينده على الفريم اللي بعده في الترتيب العشوائي، ولو خلصوا كلهم يروح لفريم النتيجة
root.goToNextQuestionOrResult = function goToNextQuestionOrResult() {
	root.questionOrderIndex += 1;
	if (root.questionOrder && root.questionOrderIndex < root.questionOrder.length) {
		root.gotoAndStop(root.questionOrder[root.questionOrderIndex]);
	} else {
		root.gotoAndStop(RESULTS_FRAME);
	}
};

root.setupCountingFrame = function setupCountingFrame() {
	// في أول setupCountingFrame
if (root._pendingTimers) {
	root._pendingTimers.forEach(clearTimeout);
}
root._pendingTimers = [];
	userInteracted = false;
	var counter = 0;
	var isLocked = false;
		root._pendingTimers = [];

	function setFlowersEnabled(enabled) {
		if (!currentCounting) {
			return;
		}
		for (var i = 1; i <= 10; i += 1) {
			var flowerChild = currentCounting["flower_" + i];
			if (flowerChild) {
				flowerChild.mouseEnabled = enabled;
			}
		}
	}

	function unlockFlowers() {
		if (root._flowersUnlockTimer) {
			clearTimeout(root._flowersUnlockTimer);
			root._flowersUnlockTimer = null;
		}
		isLocked = false;
		setFlowersEnabled(true);
	}

	// من غير duration = القفل يفضل لحد ما حد ينادي unlockFlowers (زي نهاية أنيميشن)
	function lockFlowers(duration) {
		isLocked = true;
		setFlowersEnabled(false);   // 👈 اقفل الورود

		if (root._flowersUnlockTimer) {
			clearTimeout(root._flowersUnlockTimer);
			root._flowersUnlockTimer = null;
		}

		if (typeof duration === "number") {
			root._flowersUnlockTimer = setTimeout(unlockFlowers, duration);
		}
	}

	// 👇 هوية محتوى السؤال = رقم الفريم الفعلي (بعد التنقل العشوائي بقينا واقفين على الفريم الصح مباشرة)
	var currentCounting = root["counting_" + root.currentFrame];
	window.currentQuestionNumber = currentCounting ? Number(currentCounting.name.split("_")[1]) : 0;
	// 👇 ترتيب ظهور السؤال في الجلسة (1-5) — من ترتيب الـshuffle، مش هوية المحتوى
	window.sequencePosition = (root.questionOrderIndex || 0) + 1;
	console.log("🎲 [DEBUG] setupCountingFrame — root.currentFrame:", root.currentFrame, "| currentQuestionNumber:", window.currentQuestionNumber, "| sequencePosition:", window.sequencePosition, "| progressValue:", root.progressValue, "| overly.visible:", root.overly && root.overly.visible);
	// 👇 كل سؤال ممكن يكون ليه نسخة مختلفة من count_ch_frame (بعد الـduplicate)؛
	// لو مفيش نسخة خاصة بالسؤال ده (count_ch_frame_qN)، ارجع للنسخة الأصلية
	var countChFrame = root["count_ch_frame_q" + window.currentQuestionNumber] || root.count_ch_frame;
	if (root.nums_count) {
		root.nums_count.visible = false;   // 👈 nums_count اتلغى، مش محتاجينه دلوقتي
	}
	if (root.check) {
		root.check.visible = false;   // 👈 زر check اتلغى، العد بيتأكد لوحده ويودي للاختيارات
	}
	if (root.question_sound_btn) {
		root.question_sound_btn.mouseEnabled = true;   // 👈 يترجع يشتغل مع بداية مرحلة العد (كان مقفول في الاختيارات)
	}
	if (countChFrame) {
		countChFrame.gotoAndStop(0);   // 👈 رجّعه لمرحلة العد (مهم بعد الـ retake/سؤال جديد)
	}
	if (root.pointer) {
		//root.pointer.gotoAndStop(0);   // 👈 لو كان شغال ومؤشر على اختيار من سؤال قبل كده
		root.pointer.visible = false;
	}
	var tenFrame = countChFrame && countChFrame.ten_frame;
	root.advanceScheduled = false;
	var duplicateTenFrame = root.ten_frame_duplicate || root.ten_frame_animation;
	window.onTenAnimDone = null;
	if (duplicateTenFrame) {
		window.cancelTenHold(duplicateTenFrame);
		duplicateTenFrame.stop();
		duplicateTenFrame.gotoAndStop(0);
		duplicateTenFrame.visible = false;
	}

	if (root.idel_squirrel) {
	root.idel_squirrel.stop();
	root.idel_squirrel.gotoAndStop(0);
	root.idel_squirrel.visible = false;
	}

	// 👇 انيميشن الاحتفال لما يخلص العد (مستقلة عن squirrel_2)
	if (root.celebrate) {
		root.celebrate.stop();
		root.celebrate.gotoAndStop(0);
		root.celebrate.visible = false;
	}

	// 👇 رجّع squirrel_2 وأطفاله (squirrel + celebrate اللي جواه) لحالتهم الأصلية
	window.onSquirrelCelebrateDone = null;
	if (root.squirrel_2) {
		root.squirrel_2.gotoAndStop(0);
		if (root.squirrel_2.squirrel) {
			root.squirrel_2.squirrel.stop();
			root.squirrel_2.squirrel.gotoAndStop(0);
		}
		if (root.squirrel_2.celebrate) {
			root.squirrel_2.celebrate.stop();
			root.squirrel_2.celebrate.gotoAndStop(0);
		}
	}

	// تشغيل أنيميشن العد للسؤال الحالي (يستخدم كـ hint وفي المحاولة الثالثة)
	root.hintPlaying = false;
	// 👇 عدد الورود الفعلي المطلوب عدّه في السؤال ده — بيتحسب من العناصر الموجودة فعلاً (flower_1..flower_N)
	// مش من اسم الـcounting_N (ده رقم السؤال بس، ومش لازم يساوي عدد الورد)
	var questionCount = 0;
	if (currentCounting) {
		for (var flowerCountIndex = 1; flowerCountIndex <= 10; flowerCountIndex += 1) {
			if (currentCounting["flower_" + flowerCountIndex]) {
				questionCount = flowerCountIndex;
			}
		}
	}

	// 👇 أول سؤال في الجلسة (ترتيبًا) صوته بيتشغل لما الـoverly يتقفل (closeOverlyF)؛ باقي الأسئلة بتشغّله لوحدها أول ما تتفتح
	if (window.sequencePosition !== 1 && questionSound) {
		questionSound();
	}

		root.playCountingHint = function (isHint, onDone) {

		// 👇 الـ hint التلقائي = أنيميشن السنجاب
		if (isHint) {
			var squirrel = root.idel_squirrel;
			if (!squirrel) {
				return;
			}
			root.hintPlaying = true;
			squirrel.visible = true;
			squirrel.gotoAndPlay(0);

			var squirrelMs = squirrel.totalFrames
				? (squirrel.totalFrames / lib.properties.fps) * 1000
				: 2000;

			if (root._hintStopTimer) {
				clearTimeout(root._hintStopTimer);
			}
			root._hintStopTimer = setTimeout(function () {
				squirrel.stop();
				squirrel.gotoAndStop(0);
				squirrel.visible = false;
				root.hintPlaying = false;
				root._hintStopTimer = null;
			}, squirrelMs);

			return;
		}

		// 👇 المحاولة التالتة = ten_frame_duplicate زي ما هو
		var animation = root.ten_frame_duplicate;
		if (!animation) {
			if (onDone) {
				onDone();
			}
			return;
		}
		root.hintPlaying = false;

		if (root._hintStopTimer) {
			clearTimeout(root._hintStopTimer);
			root._hintStopTimer = null;
		}

		// 👇 النهاية بتتبلّغ من جوه التايملاين (window.checkAndReset) مش بالوقت
		window.onTenAnimDone = function () {
			animation.stop();
			animation.gotoAndStop(0);
			animation.visible = false;
			if (onDone) {
				onDone();
			}
		};

		window.cancelTenHold(animation);
		dotsNo = 0;
		animation.visible = true;
		animation.gotoAndPlay(0);
	};

		root.stopCountingHint = function () {
		if (!root.hintPlaying) {
			return;
		}
		root.hintPlaying = false;
		if (root._hintStopTimer) {
			clearTimeout(root._hintStopTimer);
			root._hintStopTimer = null;
		}
		var squirrel = root.idel_squirrel;
		if (squirrel) {
			squirrel.stop();
			squirrel.gotoAndStop(0);
			squirrel.visible = false;
		}
	};


	// جدولة تكرار الـ hint كل 5 ثواني طول ما الطفل مجاوبش
		root.scheduleHint = function () {
		if (root.pointerTimer) {
			clearTimeout(root.pointerTimer);
		}
		root.pointerTimer = setTimeout(function () {
			root.pointerTimer = null;

			// 👇 السنجاب بس لو الطفل مبدأش يعد خالص
			if (counter === 0 &&
				!root.overly.visible &&
				!root.hintPlaying &&
				!isLocked) {

				root.playCountingHint(true);
			}

			root.scheduleHint();
		}, 15000);
	};

	setFlowersEnabled(true);   // 👈 اتأكد إن الورود مفتوحة مع بداية كل سؤال

	if (typeof root.progressValue === "undefined") {
		root.progressValue = 0;
	}
	if (root.progress_bar && root.progress_bar.bar) {
		root.progress_bar.bar.scaleY = root.progressValue;
	}

	counter = 0;
	if (tenFrame) {
		tenFrame.gotoAndStop(0);
	}

	if (root._flowersUnlockTimer) {
		clearTimeout(root._flowersUnlockTimer);
		root._flowersUnlockTimer = null;
	}

	// 👇 بتنفّذ دالة على كل أطفال counting_N ما عدا الورد (اللي هو أنيميشن الدخول عمليًا)
	function forEachEntryAnimChild(fn) {
		if (!currentCounting) {
			return;
		}
		for (var i = 0; i < currentCounting.numChildren; i += 1) {
			var child = currentCounting.getChildAt(i);
			var isFlower = child && child.name && child.name.indexOf("flower_") === 0;
			if (child && !isFlower) {
				fn(child);
			}
		}
	}

	root.squirrel_2.gotoAndStop(0);
	// 👇 لو الـoverly فاتح أول ما بندخل الفريم، خلي counting_N مخفية تمامًا (visible=false)
	// لحد ما الـoverly يتقفل (لوحده أو بدوسة close_overly)، ووقّف أنيميشن الدخول لحد ما تتفتح
	var overlyOpenAtEntry = !!(root.overly && root.overly.visible);
	if (currentCounting) {
		currentCounting.visible = !overlyOpenAtEntry;
		// 👇 رجّع كل وردة لفريم 0 (بالاسم، عشان تفضل شغالة حتى لو مش موجودة دلوقتي في قائمة الأطفال النشطة)
		for (var flowerIndex = 1; flowerIndex <= 10; flowerIndex += 1) {
			var resetFlower = currentCounting["flower_" + flowerIndex];
			if (resetFlower && typeof resetFlower.gotoAndStop === "function") {
				resetFlower.gotoAndStop(0);
			}
		}
		// 👇 وبعد كده رجّع الـMC نفسها لفريم 0 (مهم عشان أنيميشن الدخول تقدر تتكرر بعد الـretake)
		currentCounting.gotoAndStop(0);
		// 👇 وقّف أنيميشن الدخول (مش الورد) على فريم 0 — هتتشغّل بس لما counting_N تظهر
		// (child.paused = true بالقوة، عشان gotoAndStop لوحدها مش كانت مانعة أنيميشن Symbol10
		// إنها تكمل تشتغل لوحدها ورا الـoverly)
		forEachEntryAnimChild(function (child) {
			if (typeof child.gotoAndStop === "function") {
				child.gotoAndStop(0);
			}
			child.paused = true;
		});
	}
	if (tenFrame) {
		for (var resetIndex = 1; resetIndex <= 10; resetIndex += 1) {
			var resetButton = tenFrame["btn_" + resetIndex];
			if (resetButton) {
				resetButton.gotoAndStop(0);
			}
		}
	}
	armAllFlowers();   // 👈 رجّع كل الورود قابلة للدوس من الأول (مهم بعد الـ retake)

	// خريطة أصوات الأرقام
	var numberSounds = {
		1: "one",
		2: "two",
		3: "three",
		4: "four",
		5: "five",
		6: "six",
		7: "seven",
		8: "eight",
		9: "nine",
		10: "ten"
	};

	var currentNumberSoundInstance = null;

		function playNumberSound(num, isAuto) {
		if (isAuto) {
			createjs.Sound.play("ClickSound2");
			return null;
		}

		var soundId = numberSounds[num];
		if (!soundId) {
			return null;
		}
		return playVoice(soundId);   // 👈 بيقطع count_and_color وأي رقم قبله، وبيرجّع الـsound instance
	}

	function updateTenFrameDisplay(count) {
		if (!tenFrame) {
			return;
		}
		for (var i = 1; i <= 10; i += 1) {
			var b = tenFrame["btn_" + i];
			if (b) {
				b.gotoAndStop(i <= count ? 1 : 0);
			}
		}
	}

	function countLitFlowers() {
		if (!currentCounting) {
			return 0;
		}
		var lit = 0;
		for (var i = 1; i <= 10; i += 1) {
			var flowerChild = currentCounting["flower_" + i];
			if (flowerChild && flowerChild.currentFrame === 1) {
				lit += 1;
			}
		}
		return lit;
	}

	// بتفتح وردة للدوس عليها (فريم 0 + مينفعش تتلمس + هاندلر جديد)
	function armFlower(flower) {
		if (!flower) {
			return;
		}
		flower.gotoAndStop(0);
		flower.mouseEnabled = true;
		flower.cursor = "pointer";
		flower.removeAllEventListeners("click");
		flower.addEventListener("click", toggleFlower);
	}

	function armAllFlowers() {
		for (var i = 1; i <= 10; i += 1) {
			armFlower(currentCounting && currentCounting["flower_" + i]);
		}
	}

	// الطفل بيدوس على الوردة نفسها؛ أزرار الـ ten_frame بترد بس بالترتيب
	// حسب عدد الورود المضاءة دلوقتي (بغض النظر عن أي وردة اتدوست بالظبط)
	// كل وردة بتتعد مرة واحدة بس — بعد ما تضيء (فريم 1) بتشيل الهاندلر من عليها
	// 👇 بعد ما صوت العد (رقم آخر وردة) يخلص: احتفال + صوت نجاح، واستنى الصوت ده كمان يخلص + ثانيتين، وبعدين روح لفريم الاختيارات
	function scheduleChoiceTransition() {
		if (root.advanceScheduled) {
			return;
		}
		root.advanceScheduled = true;

		if (root.pointerTimer) {
			clearTimeout(root.pointerTimer);
			root.pointerTimer = null;
		}
		root.stopCountingHint();

		// 👇 احتفال العد الصح + صوت النجاح قبل ما نروح لفريم الاختيارات
		if (root.celebrate) {
			root.celebrate.visible = true;
			root.celebrate.gotoAndPlay(0);
			var celebrateMs = root.celebrate.totalFrames
				? (root.celebrate.totalFrames / lib.properties.fps) * 1000
				: 2000;
			root._pendingTimers.push(setTimeout(function () {
				if (root.celebrate) {
					root.celebrate.stop();
					root.celebrate.gotoAndStop(0);
					root.celebrate.visible = false;
				}
			}, celebrateMs));
		}
		// 👇 صوت النجاح العادي بس هنا (من غير صوت successVoicesMap — ده بقى مخصوص لسؤال الاختيارات)
		// والتنقل لفريم الاختيارات معتمد على onComplete بتاعه هو نفسه — على طول من غير أي استنى
		function goToChoiceFrame() {
			if (countChFrame) {
				countChFrame.gotoAndPlay(1);
			}
		}
		var successInstance = createjs.Sound.play("success");
		if (successInstance && successInstance.on) {
			successInstance.on("complete", function handler() {
				successInstance.off && successInstance.off("complete", handler);
				goToChoiceFrame();
			});
		} else {
			goToChoiceFrame();
		}
	}

	function toggleFlower(event) {
		var flower = event.currentTarget;
		if (flower.currentFrame === 1) {
			return;   // 👈 اتعدّت خلاص، مش المفروض أصلاً تقدر تدوس عليها تاني
		}

		userInteracted = true;

		if (root.pointerTimer) {
			clearTimeout(root.pointerTimer);
			root.pointerTimer = null;
		}
		if (root.pointer) {
			root.pointer.gotoAndStop(0);
			root.pointer.visible = false;
		}
		root.stopCountingHint();

		flower.gotoAndStop(1);
		flower.mouseEnabled = false;
		flower.removeAllEventListeners("click");   // 👈 شيل الهاندلر، مينفعش تتدوس تاني

		counter = countLitFlowers();
		updateTenFrameDisplay(counter);
		var numberSoundInstance = playNumberSound(counter, event.isAuto);

		root.scheduleHint();

		if (counter === questionCount) {
			// 👇 امنع زرار صوت السؤال من هنا: لو اتدوس هيوقف صوت آخر وردة (currentVoiceInstance)
			// من غير ما يبعت "complete"، فالانتقال للاختيارات هيفضل عالق للأبد
			if (root.question_sound_btn) {
				root.question_sound_btn.mouseEnabled = false;
			}

			// 👇 استنى صوت رقم آخر وردة (اللي بيطلع لما تدوس عليها) يخلص، وبعدين ابدأ احتفال الإجابة الصح
			if (numberSoundInstance && numberSoundInstance.on) {
				numberSoundInstance.on("complete", function handler() {
					numberSoundInstance.off && numberSoundInstance.off("complete", handler);
					scheduleChoiceTransition();
				});
			} else {
				scheduleChoiceTransition();
			}
		}
	}

	// ========================================
	// فريم الاختيارات (ch_1: select1/select2/select3 + num_opt1/2/3)
	// بتتنده من count_ch_frame أول ما يوصل لفريم 1 (window.setupChoiceFrame)
	// ========================================
	window.setupChoiceFrame = function (chFrameMc) {
		var ch = chFrameMc && chFrameMc.ch_1;
		if (!ch) {
			return;
		}

		// 👈 pointer بقى جوه ch_1 نفسه (جنب select1/2/3) مش على count_ch_frame ولا الـ root
		var pointer = ch.pointer;
		if (pointer) {
		//	pointer.gotoAndStop(0);   // 👈 يبدأ مخفي مع كل سؤال جديد
			pointer.visible = false;
		}

		// 👇 أنيميشن الرقم التساعدي (جوه ten_frame) — بيبان بس من المحاولة الثانية الغلط وبعدين
		var numberAnimation = tenFrame && tenFrame.number_animation;
		if (numberAnimation) {
			numberAnimation.removeAllEventListeners("tick");   // 👈 امسح أي مستمع Tick قديم فاضل من محاولة قبل كده (retake)
			numberAnimation.gotoAndStop(0);   // 👈 يرجع مخفي/فاضي مع كل سؤال جديد
		}
		if (tenFrame) {
			tenFrame.gotoAndStop(0);   // 👈 number_animation مخفي (_off) لحد ما نحتاجه
		}

		// 👇 ديناميكي بالكامل: مبنعتمدش على أرقام فريمات ثابتة — بنستخدم نظام اللابلز
		// نفسه (num_6, num_7, ...) اللي مضبوط جوه Symbol1 عشان نعرف نوقف فين بالظبط
		// (resolve() بترجع رقم الفريم من غير ما نحتاج نقفز عليه الأول زي قبل كده).
		// 👇 الوقفة نفسها معتمدة على حدث "tick" بتاع CreateJS (نفس ساعة الأنيميشن بالظبط)
		// مش setTimeout — عشان setTimeout ممكن ياخد جزء من الثانية فرق عن التوقيت الحقيقي
		// فيبان "خطفة" في آخر الأنيميشن.
		function playNumberAnimationTo(targetValue) {
			if (!numberAnimation || !numberAnimation.timeline) {
				return;
			}
			var targetLabel = "num_" + targetValue;
			var targetFrame = numberAnimation.timeline.resolve(targetLabel);
			if (typeof targetFrame !== "number" || isNaN(targetFrame)) {
				return;   // 👈 مفيش ليبل بالاسم ده في number_animation
			}
			numberAnimation.removeAllEventListeners("tick");
			numberAnimation.gotoAndPlay(0);
			function checkFrame() {
				if (numberAnimation.currentFrame >= targetFrame) {
					numberAnimation.removeEventListener("tick", checkFrame);
					numberAnimation.gotoAndStop(targetFrame);
				}
			}
			numberAnimation.addEventListener("tick", checkFrame);
		}

		// 👇 زرار صوت سؤال العد مالوش لازمة هنا؛ اقفله لحد ما نرجع لمرحلة العد تاني
		if (root.question_sound_btn) {
			root.question_sound_btn.mouseEnabled = false;
		}

		// 👇 صوت "اختار الرقم الصح" بيتقال تلقائي أول ما فريم الاختيارات يظهر
		chooseSound();

		// 👇 وبردو أي وقت يدوس على ch_sound
		if (ch.ch_sound) {
			ch.ch_sound.mouseEnabled = true;
			ch.ch_sound.cursor = "pointer";
			ch.ch_sound.removeAllEventListeners("click");
			ch.ch_sound.addEventListener("click", chooseSound);
		}

		function shuffleArray(arr) {
			for (var i = arr.length - 1; i > 0; i -= 1) {
				var j = Math.floor(Math.random() * (i + 1));
				var tmp = arr[i];
				arr[i] = arr[j];
				arr[j] = tmp;
			}
		}

		var correctValue = questionCount;
		var pool = [];
		// 👇 مدى الأرقام البديلة (الغلط) في الاختيارات — من 6 لـ10 عشان يفضل قريب من مدى اللعبة الحقيقي
		for (var n = 6; n <= 10; n += 1) {
			if (n !== correctValue) {
				pool.push(n);
			}
		}
		shuffleArray(pool);
		var values = [correctValue, pool[0], pool[1]];
		shuffleArray(values);   // 👈 مكان الرقم الصح بين الـ 3 اختيارات بيتغير كل مرة

		var selects = [ch.select1, ch.select2, ch.select3];
		var numFieldNames = ["num_opt1", "num_opt2", "num_opt3"];
		var wrongPicks = 0;
		var answered = false;

		// 👇 النقط حسب عدد المحاولات اللي الطفل استنفذها لحد ما يجاوب صح
		function getChoicePoints(attemptsUsed) {
			if (attemptsUsed <= 1) {
				return 3;
			}
			if (attemptsUsed === 2) {
				return 2;
			}
			return 1;
		}

		function disableAllSelects() {
			for (var i = 0; i < selects.length; i += 1) {
				if (selects[i]) {
					selects[i].mouseEnabled = false;
					selects[i].removeAllEventListeners("click");
				}
			}
		}

		// 👇 يحرّك الـpointer (جوه ch_1) فوق رقم الاختيار الصح ويظهرها (من المحاولة التالتة الغلط وبعدين)
		// بعد شوية بتختفي لوحدها — هي استرشادية بس مش المفروض تفضل ظاهرة
		function showPointerAtCorrectSelect() {
			if (!pointer) {
				return;
			}
			var correctIndex = values.indexOf(correctValue);
			var correctSelect = selects[correctIndex];
			if (!correctSelect) {
				return;
			}
			var numField = correctSelect[numFieldNames[correctIndex]];
			var target = numField || correctSelect;   // 👈 التارجت بقى الرقم نفسه مش الاختيار كله

			// 👇 نص مربع النص (100x64.25) مش الزاوية بتاعته، عشان الـpointer ينزل على الرقم مباشرة
			var targetX = numField ? 50 : 0;
			var targetY = numField ? 32.125 : 0;
			var globalPoint = target.localToGlobal(targetX, targetY);
			var localPoint = ch.globalToLocal(globalPoint.x, globalPoint.y);
			pointer.x = localPoint.x;
			pointer.y = localPoint.y;
			pointer.visible = true;
			pointer.mouseEnabled = false;   // 👈 بس بيأشر، مينفعش يتدوس عليه أو يعمل حجب للدوس على الاختيار
			pointer.gotoAndStop(0);   // 👈 فريم واحد بس دلوقتي، مفيش أنيميشن نشغّلها

			// 👇 استرشادية بس — تظهر شوية ثانية وتختفي لوحدها (مش هتستنى إجابة)
			if (root._pointerHintTimer) {
				clearTimeout(root._pointerHintTimer);
			}
			root._pointerHintTimer = setTimeout(function () {
				root._pointerHintTimer = null;
				hidePointer();
			}, 1500);
		}

		function hidePointer() {
			if (root._pointerHintTimer) {
				clearTimeout(root._pointerHintTimer);
				root._pointerHintTimer = null;
			}
			if (pointer) {
				pointer.gotoAndStop(0);
				pointer.visible = false;
			}
		}

		function onSelectClick(select, index) {
			if (answered) {
				return;
			}

			createjs.Sound.play("ClickSound");

			if (values[index] !== correctValue) {
				wrongPicks += 1;
				select.gotoAndStop(1);   // 👈 الحالة التانية: غلط + shake
				shake(select);
				select.mouseEnabled = false;
				select.removeAllEventListeners("click");
				playRandomErrorVoice();   // 👈 صوت غلط عشوائي، مش بيتكرر مرتين ورا بعض

				// 👇 من المحاولة الثانية الغلط بالظبط: وري أنيميشن الرقم وقّفه عند الرقم الصح (num_6 لحد num_10)
				if (wrongPicks === 2 && numberAnimation && tenFrame) {
					tenFrame.gotoAndStop(1);   // 👈 يظهر number_animation (كان مخفي بـ_off)
					playNumberAnimationTo(correctValue);   // 👈 يشغّل من الأول ويوقف عند الرقم الصح
				}

				// 👇 من المحاولة التالتة (يعني بعد 3 غلطات) وبعدين: أشّر على الاختيار الصح
				if (wrongPicks >= 3) {
					showPointerAtCorrectSelect();
				}

				// 👇 بعد الـ shake رجّعه للحالة الطبيعية تاني عشان يقدر يدوس عليه تاني
				root._pendingTimers.push(setTimeout(function () {
					if (answered) {
						return;
					}
					select.gotoAndStop(0);
					select.mouseEnabled = true;
					select.cursor = "pointer";
					select.removeAllEventListeners("click");
					select.addEventListener("click", function () {
						onSelectClick(select, index);
					});
				}, 600));
				return;
			}

			answered = true;
			hidePointer();
			select.gotoAndStop(2);   // 👈 الحالة التالتة: صح
			disableAllSelects();

			var attemptsUsed = wrongPicks + 1;   // 👈 عدد المحاولات = الغلط + المحاولة الصح نفسها
			var earnedPoints = getChoicePoints(attemptsUsed);
			window.score = (window.score || 0) + earnedPoints;
			window.completedCount = (window.completedCount || 0) + 1;

			addInteraction(
				"q" + window.currentQuestionNumber,
				"numeric",
				String(correctValue),
				"correct"
			);

			createjs.Sound.play("success_option_1", {
				volume: 0.05   // 👈 وطّيتها عشان متغطيش على صوت successVoicesMap
			});

			// 👇 التقدّم حسب ترتيب ظهور السؤال في الجلسة (1 من 5)، مش هوية محتواه العشوائية
			root.progressValue = Math.min(1, window.sequencePosition / 5);
			if (root.progress_bar && root.progress_bar.bar) {
				createjs.Tween.removeTweens(root.progress_bar.bar);
				createjs.Tween.get(root.progress_bar.bar)
					.to({
						scaleY: root.progressValue
					}, 350, createjs.Ease.quadOut);
			}

			// 👇 celebrate والسنجاب يظهروا فورًا (بصريًا بس، مش شرط للتنقل)
			if (root.squirrel_2) {
				root.squirrel_2.gotoAndStop(1);
				if (root.squirrel_2.celebrate) {
					root.squirrel_2.celebrate.gotoAndPlay(0);
				}
				if (root.squirrel_2.squirrel) {
					root.squirrel_2.squirrel.gotoAndPlay(0);
				}
			}

			// 👇 صوت النجاح حسب ترتيب ظهور السؤال في الجلسة (1-5)، مش هوية محتواه العشوائية
			// والتنقل للسؤال العشوائي اللي بعده (أو النتيجة لو خلصوا) معتمد على onComplete بتاعه
			var startedOnFrame = root.currentFrame;
			playRandomSuccessVoice(window.sequencePosition, function () {
				if (root.currentFrame !== startedOnFrame) {
					return;   // 👈 حصل retake أو تنقل تاني في الأثناء، متنقلش بفريم قديم
				}
				root.goToNextQuestionOrResult();
			});
		}

		for (var idx = 0; idx < selects.length; idx += 1) {
			(function (select, index) {
				if (!select) {
					return;
				}
				select.gotoAndStop(0);   // 👈 الحالة الأولى: طبيعية
				select.mouseEnabled = true;
				select.cursor = "pointer";
				var numField = select[numFieldNames[index]];
				if (numField) {
					numField.text = String(values[index]);
				}
				select.removeAllEventListeners("click");
				select.addEventListener("click", function () {
					onSelectClick(select, index);
				});
			})(selects[idx], idx);
		}
	};

	// 👇 فتح الدوس على الورد معتمد على إن أنيميشن الدخول تخلص، بالظبط زي القديم
	window.onEntryAnimDone = function () {
		window.onEntryAnimDone = null;
		unlockFlowers();
		root.scheduleHint();

		// 👇 إصلاح دفاعي: بعض الورد بترجع لحالة "معدودة" لوحدها فور ما تتضاف كطفل فعلي
		// (بعد ما counting_N توصل فريم1 وTween الإضافة يشتغل، يعني بعد الـTick اللي جاي مباشرة)
		// فبنعيد تسليحهم تاني بعد أول Tick يضمن استقرارهم على فريم 0
		root._pendingTimers.push(setTimeout(function () {
			armAllFlowers();
		}, 50));
	};

	// 👇 وري counting_N وشغّل أنيميشن الدخول من فريمها الأول — مرة واحدة بس
	function revealEntryAnim() {
		if (currentCounting) {
			currentCounting.visible = true;
		}
		forEachEntryAnimChild(function (child) {
			if (typeof child.gotoAndPlay === "function") {
				child.gotoAndPlay(0);
			}
		});
		// 👇 مهلة أمان لو أنيميشن الدخول ما بلّغش — بتتحسب من هنا (بعد ما فعليًا بدأت)
		root._pendingTimers.push(setTimeout(function () {
			if (window.onEntryAnimDone) {
				window.onEntryAnimDone();
			}
		}, 5000));
	}

	// 👇 لو الـoverly كان فاتح أول ما دخلنا الفريم، استناها تتقفل الأول (مرة واحدة بس أول ما نفتح
	// السؤال — مش لما يتفتح تاني بزرار الـinfo)، وبعدين شغّل أنيميشن الدخول
	root.onOverlyClosedForCounting = null;
	if (overlyOpenAtEntry) {
		root.onOverlyClosedForCounting = function () {
			root.onOverlyClosedForCounting = null;
			revealEntryAnim();
		};
	} else {
		revealEntryAnim();
	}

	lockFlowers();   // من غير مهلة تلقائية هنا — المهلة الاحتياطية بقت جوه revealEntryAnim
};


console.log("🎲 [DEBUG] frame1 tail — isFirstGameStart:", isFirstGameStart, "| questionOrder:", root.questionOrder, "| questionOrderIndex:", root.questionOrderIndex);
if (isFirstGameStart) {
	root.progressValue = 0;
	// 👇 لو لسه معملناش شافل للأسئلة (أول تحميل حقيقي)، اعمله دلوقتي — لو جاي بعد Retake
	// يبقى الترتيب الجديد اتعمل خلاص قبل كده في زرار الـRetake نفسه
	if (!root.questionOrder) {
		root.generateQuestionOrder();
	}
	// 👇 روح لأول سؤال في الترتيب العشوائي — لو هو فريم1 نفسه شغّله مباشرة، غير كده اتنقل لفريمه
	var firstQuestionFrame = root.questionOrder[root.questionOrderIndex];
	console.log("🎲 [DEBUG] firstQuestionFrame:", firstQuestionFrame);
	if (firstQuestionFrame && firstQuestionFrame !== 1) {
		console.log("🎲 [DEBUG] هينتقل لفريم:", firstQuestionFrame);
		root.gotoAndStop(firstQuestionFrame);
	} else {
		console.log("🎲 [DEBUG] هيشغل setupCountingFrame مباشرة (فريم1)");
		root.setupCountingFrame();
	}
} else {
	// 👇 رجعنا هنا لأن محتوى Q1 وقع في ترتيب عشوائي متأخر، مش بداية اللعبة —
	// شغّل بس محتوى السؤال ده من غير ما نعيد تهيئة اللعبة كلها (overlay/progressValue/shuffle جديد)
	console.log("🎲 [DEBUG] رجعنا لفريم1 عشان محتوى Q1 وقع متأخر في الترتيب — هيشغل setupCountingFrame بس");
	root.setupCountingFrame();
}

this.stop();

var root = this;

if (bgMusicInstance) {
	bgMusicInstance.stop();
	bgMusicInstance = null;
}

/* =========================================
   بيانات اللعبة
========================================= */

var score = window.score || 0;
var maxScore = 15;

var percent = maxScore > 0
	? Math.round((score / maxScore) * 100)
	: 0;

console.log("score:", score, "/ maxScore:", maxScore, "→", percent + "%");

/* =========================================
   عدد النجوم
   80%+ → 3 | 50-79% → 2 | أقل من 50% → 1
========================================= */

var starsCount;

if (percent >= 80) {
	starsCount = 3;
} else if (percent >= 50) {
	starsCount = 2;
} else {
	starsCount = 1;
}

root.result.stars_animation.s1.gotoAndStop(starsCount >= 1 ? 1 : 0);
root.result.stars_animation.s2.gotoAndStop(starsCount >= 2 ? 1 : 0);
root.result.stars_animation.s3.gotoAndStop(starsCount >= 3 ? 1 : 0);

/* =========================================
   اللغة والداتا
========================================= */

var lang = window.language || "EN";
var data = window.gameData;

/* =========================================
   النسبة %
========================================= */

if (root.final_score) {
	root.final_score.text = percent + "%";
}

/* =========================================
   مستوى النتيجة والصوت
========================================= */

var level;

if (percent >= 80) {
	level = "great";
	createjs.Sound.play("success", { volume: 0.2 });
}
else if (percent >= 50) {
	level = "goodjob";
	createjs.Sound.play("success", { volume: 0.2 });
}
else {
	level = "good";
	createjs.Sound.play("success", { volume: 0.2 });
}

/* =========================================
   عنوان النتيجة ونصها
========================================= */

if (root.res_title) {
	root.res_title.text = data.results[level].title[lang];
}

if (root.result_txt) {
	root.result_txt.text = data.results[level][lang];
	root.result_txt.lineHeight = root.result_txt.getMeasuredLineHeight() * 1.1;
}

/* =========================================
   Result Animation
========================================= */

if (root.result) {
	root.result.visible = true;
	root.result.gotoAndStop(starsCount === 1 ? 1 : 0);
}

/* =========================================
   زر الإعادة
========================================= */

if (root.result.retake_btn) {

	root.result.retake_btn.cursor = "pointer";
	root.result.retake_btn.removeAllEventListeners("click");

	currentStep = 0;

	root.result.retake_btn.on("click", function () {

		createjs.Sound.play("ClickSound");

		window.score = 0;
		window.completedCount = 0;
		root.generateQuestionOrder();   // 👈 ترتيب عشوائي جديد لمحتوى الأسئلة مع كل Retake
		root.gameStarted = false;   // 👈 المرة الجاية اللي نوصل فيها فريم1 تتعامل كبداية جديدة فعلاً (overlay/progressValue)

		// 👇 اقفل شاشة النتيجة تمامًا قبل الرجوع، عشان متفضلش فوق اللعبة وتمنع اللمس
		root.result.visible = false;

		root.gotoAndStop(0);

		window.iosFixApplied = true;
	});
}

/* =========================================
   Send object to app / SCORM
========================================= */

let resultData = {

	"result": {

		"completion": true,

		"success": percent >= 50,

		"score": {

			"scaled": percent / 100,

			"raw": percent,

			"min": 0,

			"max": 100
		}
	},

	"interactions": window.interactions || []
};

window.scormHandlerReady.then(function () {

	sendScormData(resultData);

}).catch(function () {

	console.error('Could not send data - handler not loaded');
});

