// Pause all sounds when app/tab loses focus
var bgMusicInstance = null;
var musicEnabled = true;
var pendingIOSResume = false;

// سجل مركزي للأصوات اللي بنحتاج نوقفها من أي مكان
window.soundInstances = {};

function resumeIOSAudioOnGesture() {
    if (!pendingIOSResume) return;
    pendingIOSResume = false;

    if (window.createjs && createjs.WebAudioPlugin && createjs.WebAudioPlugin.context) {
        var ctx = createjs.WebAudioPlugin.context;
        if (ctx.state !== "running") {
            ctx.resume();
        }
    }

    if (!bgMusicInstance) {
        bgMusicInstance = createjs.Sound.play("bgMusic", { loop: -1, volume: 0.02 });
    }
    bgMusicInstance.paused = !musicEnabled;
}
document.addEventListener("touchend", resumeIOSAudioOnGesture, true);
document.addEventListener("click", resumeIOSAudioOnGesture, true);

document.addEventListener("visibilitychange", function () {
    if (document.hidden) {
        createjs.Sound.muted = true;    // 👈 اكتم كل الأصوات
    } else {
        createjs.Sound.muted = false;   // 👈 رجّع الصوت
    }

    // منطق الـ bgMusic الموجود عندك زي ما هو
    if (!bgMusicInstance) return;
    if (document.hidden) {
        bgMusicInstance.paused = true;
    } else {
        if (isIOS && /iPhone|iPod/.test(navigator.userAgent)) {
            bgMusicInstance.paused = true;
            pendingIOSResume = true;
        } else if (isIOS) {
            bgMusicInstance.paused = false;
            createjs.Sound.resume();
            bgMusicInstance.paused = true;
            bgMusicInstance.paused = false;
        } else {
            bgMusicInstance.paused = !musicEnabled;
        }
    }
});

window.addEventListener("blur", function () {
    createjs.Sound.muted = true;        // 👈
    if (bgMusicInstance) {
        bgMusicInstance.paused = true;
    }
});

window.addEventListener("focus", function () {   // 👈 handler جديد
    createjs.Sound.muted = false;
    if (bgMusicInstance) {
        bgMusicInstance.paused = !musicEnabled;
    }
});

window.addEventListener("pagehide", function () {
    createjs.Sound.muted = true;        // 👈
    if (bgMusicInstance) {
        bgMusicInstance.paused = true;
    }
});



