// =================================================
// OPTIONAL ACTIVITY API - LOGO ONLY
// =================================================

var logoURL = null;
var logoApiStarted = false;
var logoApiFinished = false;

var logoActivityID = null;
var logoUserToken = null;

var logoScriptsPath = "../../../../library/scripts/";


// =================================================
// READ ACTIVITY PARAMETERS
// =================================================

(function initLogoApi() {

    try {
        var params = new URLSearchParams(window.location.search);

        logoActivityID = params.get("id");
        logoUserToken = params.get("token");

        console.log("🟢 Logo API - activityID:", logoActivityID);

        // No activity ID = local/direct launch
        // Do absolutely nothing.
        if (!logoActivityID) {
            console.log("ℹ️ Logo API skipped: no activity ID.");
            logoApiFinished = true;
            return;
        }

        loadLogoActivityLoader();

    } catch (error) {

        console.warn(
            "⚠️ Logo API initialization failed. Activity will continue normally.",
            error
        );

        logoApiFinished = true;
    }

})();

// =================================================
// LOAD ACTIVITY LOADER - LOGO ONLY
// =================================================

function loadLogoActivityLoader() {

    if (logoApiStarted) return;

    logoApiStarted = true;

    var script = document.createElement("script");

    script.type = "module";
    script.src = logoScriptsPath + "activity-loader.js";

    script.onload = function () {

        console.log(
            "✅ Activity Loader loaded for logo:",
            script.src
        );

        loadLogoFromAPI();

    };

    script.onerror = function (error) {

        console.warn(
            "⚠️ Activity Loader failed to load. Continuing without logo.",
            error
        );

        logoApiFinished = true;
    };

    document.head.appendChild(script);
}


// =================================================
// GET LOGO FROM ACTIVITY API
// =================================================

async function loadLogoFromAPI() {

    if (!logoActivityID) {
        logoApiFinished = true;
        return;
    }

    if (typeof getActivityData !== "function") {

        console.warn(
            "⚠️ getActivityData is not available. Continuing without logo."
        );

        logoApiFinished = true;
        return;
    }

    try {

        console.log("🔄 Loading activity data for logo...");

        var data = await getActivityData(
            logoActivityID,
            logoUserToken
        );

        console.log("📦 Activity API response:", data);

        if (!data || !data.status) {

            console.warn(
                "⚠️ Activity API returned no valid data. Continuing without logo."
            );

            logoApiFinished = true;
            return;
        }

        // We ONLY care about the logo.
        logoURL = data.logo || null;

        logoApiFinished = true;

        if (!logoURL) {

            console.warn(
                "⚠️ Activity has no logo URL. Continuing without logo."
            );

            return;
        }

        console.log("🖼️ Logo URL received:", logoURL);

        waitForLogoStageAndLoad();

    } catch (error) {

        console.warn(
            "⚠️ Logo API request failed. Activity will continue normally.",
            error
        );

        logoApiFinished = true;
    }
}

// =================================================
// WAIT FOR ANIMATE LOGO TARGET
// =================================================

function waitForLogoStageAndLoad() {

    if (!logoURL) return;

    if (
        typeof exportRoot !== "undefined" &&
        exportRoot &&
        exportRoot.logo_mc
    ) {

        loadLogoIntoMC(
            exportRoot.logo_mc,
            logoURL
        );

        return;
    }

    setTimeout(
        waitForLogoStageAndLoad,
        50
    );
}

// =================================================
// LOAD REMOTE LOGO INTO logo_mc
// =================================================

function loadLogoIntoMC(mc, url) {

    if (!mc || !url) {
        return;
    }

    var container = mc.getChildAt(0);

    if (!container) {
        container = mc;
    }

    var bounds = container.nominalBounds || {
        width: 100,
        height: 120
    };

    // Remove existing logo content
    if (container.removeAllChildren) {
        container.removeAllChildren();
    } else {

        mc.removeAllChildren();
        container = mc;
    }

    var img = new Image();

    img.onload = function () {

        try {

            var bitmap = new createjs.Bitmap(img);

            bitmap.scaleX =
                bounds.width / img.width;

            bitmap.scaleY =
                bounds.height / img.height;

            bitmap.x = 0;
            bitmap.y = 0;

            container.addChild(bitmap);

            stage.update();

            console.log(
                "✅ Logo loaded successfully."
            );

        } catch (error) {

            console.warn(
                "⚠️ Failed to render logo.",
                error
            );
        }
    };

    img.onerror = function () {

        console.warn(
            "⚠️ Logo image failed to load:",
            url
        );

        // IMPORTANT:
        // Do not stop or affect the activity.
    };

    img.src = url;
}




