};

var currentSuccessVoiceInstance = null;

function playRandomSuccessVoice(questionNumber, onComplete) {

  if (typeof questionNumber === "undefined") {
    questionNumber = window.currentQuestionNumber;
  }

  var voices = successVoicesMap[questionNumber];

  if (!voices || !voices.length) {
    console.warn("🔇 No success voices for question:", questionNumber);
    if (onComplete) onComplete();
    return;
  }

  var readyVoices = voices.filter(function (id) {
    return createjs.Sound.loadComplete(id);
  });

  // كله جاهز؟ شغّل واحد عشوائي على طول
  if (readyVoices.length) {
    playSuccessVoiceNow(
      readyVoices[Math.floor(Math.random() * readyVoices.length)],
      questionNumber,
      onComplete
    );
    return;
  }

  // مفيش حاجة جاهزة: استنى أول صوت من القايمة يخلص تحميل
  console.warn("⏳ Voices still loading for question:", questionNumber, "- waiting...");

  var played = false;

  function onVoiceLoaded(e) {
    if (played) return;
    if (voices.indexOf(e.id) === -1) return;

    played = true;
    createjs.Sound.off("fileload", onVoiceLoaded);
    playSuccessVoiceNow(e.id, questionNumber, onComplete);
  }

  createjs.Sound.on("fileload", onVoiceLoaded);

  // مهلة قصوى: لو عدت ثانيتين ومفيش حاجة اتحملت، بلاش الصوت خالص
  setTimeout(function () {
    if (!played) {
      played = true;
      createjs.Sound.off("fileload", onVoiceLoaded);
      console.warn("🔇 Gave up waiting for voices, question:", questionNumber);
      if (onComplete) onComplete();
    }
  }, 2000);
}

function playSuccessVoiceNow(soundId, questionNumber, onComplete) {
  if (currentErrorVoiceInstance) {          // 👈
    currentErrorVoiceInstance.stop();
    currentErrorVoiceInstance = null;
  }
  if (currentSuccessVoiceInstance) {
    currentSuccessVoiceInstance.stop();
    currentSuccessVoiceInstance = null;
  }
  if (window.currentVoiceInstance) {          // 👇 اقطع صوت العنوان/الأرقام لو شغال
    window.currentVoiceInstance.stop();
    window.currentVoiceInstance = null;
  }
  currentSuccessVoiceInstance = createjs.Sound.play(soundId);
  window.currentSuccessVoiceInstance = currentSuccessVoiceInstance;
  if (onComplete && currentSuccessVoiceInstance) {
    currentSuccessVoiceInstance.on("complete", function handler() {
      currentSuccessVoiceInstance && currentSuccessVoiceInstance.off && currentSuccessVoiceInstance.off("complete", handler);
      onComplete();
    });
  }
  console.log("🎉 Playing success voice:", soundId, "for question", questionNumber);
}


/* =================================================
   RANDOM ERROR VOICES (مصفوفة واحدة لكل الأسئلة)
================================================= */
var errorVoices = [
  "v0031_oops_opt1",
  "v0032_hmmm_try_again",
  "v0036_look_carefully",
  "v0037_lets_think",
  "v0039_come_on_you_can_do_it",
  "v0043_lets_do_it_together_opt1",
  "v0044_one_more_try",
  "v0042_come_on_almost_there"
];

var currentErrorVoiceInstance = null;
var lastErrorVoiceId = null;

function playRandomErrorVoice() {

  var readyVoices = errorVoices.filter(function (id) {
    return createjs.Sound.loadComplete(id);
  });

  if (readyVoices.length) {

    // استبعد آخر صوت اتنده عشان مايتكررش ورا بعضه
    var pool = readyVoices.filter(function (id) {
      return id !== lastErrorVoiceId;
    });
    if (!pool.length) {
      pool = readyVoices;
    }

    playErrorVoiceNow(pool[Math.floor(Math.random() * pool.length)]);
    return;
  }

  console.warn("⏳ Error voices still loading - waiting...");

  var played = false;

  function onVoiceLoaded(e) {
    if (played) return;
    if (errorVoices.indexOf(e.id) === -1) return;

    played = true;
    createjs.Sound.off("fileload", onVoiceLoaded);
    playErrorVoiceNow(e.id);
  }

  createjs.Sound.on("fileload", onVoiceLoaded);

  setTimeout(function () {
    if (!played) {
      played = true;
      createjs.Sound.off("fileload", onVoiceLoaded);
      console.warn("🔇 Gave up waiting for error voices");
    }
  }, 2000);
}

function playErrorVoiceNow(soundId) {
  if (currentSuccessVoiceInstance) {
    currentSuccessVoiceInstance.stop();
    currentSuccessVoiceInstance = null;
  }
  if (currentErrorVoiceInstance) {
    currentErrorVoiceInstance.stop();
    currentErrorVoiceInstance = null;
  }
  if (window.currentVoiceInstance) {          // 👇 اقطع صوت العنوان/الأرقام لو شغال
    window.currentVoiceInstance.stop();
    window.currentVoiceInstance = null;
  }
  lastErrorVoiceId = soundId;
  currentErrorVoiceInstance = createjs.Sound.play(soundId);
  window.currentErrorVoiceInstance = currentErrorVoiceInstance;
  console.log("❌ Playing error voice:", soundId);
}


// =================================================
// DYNAMIC OPTION SOUNDS
// =================================================

window.optionSoundsMap = {};
window.currentOptionSoundInstance = null;

function registerOptionSounds(data) {

  if (!data || !data.elements) return;

  window.optionSoundsMap = {};

  data.elements.forEach(function (element) {

    if (!element.options) return;

    element.options.forEach(function (option, optionIndex) {

      if (!option.audio) return;

      var soundId =
        "option_" +
        element.id +
        "_" +
        (optionIndex + 1);

      var soundPath = templateDataURL
        ? templateDataURL + option.audio
        : option.audio;

      try {

        var registerResult = createjs.Sound.registerSound(
          soundPath,
          soundId
        );

        // لو CreateJS رفض الملف مباشرة
        if (!registerResult) {

          console.warn(
            "⚠️ Sound skipped:",
            soundId,
            soundPath
          );

          return;
        }

        // نسجله Pending لحد ما يتحمل فعلياً
        window.optionSoundsMap[soundId] = {
          id: soundId,
          src: soundPath,
          loaded: false
        };

        console.log(
          "🔄 Registering option sound:",
          soundId,
          soundPath
        );

      } catch (error) {

        // أي مشكلة في الملف أو الـ type
        // نتجاهل الصوت ونكمل عادي

        delete window.optionSoundsMap[soundId];

        console.warn(
          "⚠️ Invalid sound skipped:",
          soundId,
          soundPath,
          error.message
        );

      }

    });

  });

}

createjs.Sound.on("fileload", function (event) {

  var soundData =
    window.optionSoundsMap[event.id];

  if (!soundData) return;

  soundData.loaded = true;

  console.log(
    "✅ Option sound ready:",
    event.id
  );

});


createjs.Sound.on("fileerror", function (event) {

  var soundData =
    window.optionSoundsMap[event.id];

  if (!soundData) return;

  console.warn(
    "⚠️ Option sound failed and skipped:",
    event.id,
    soundData.src
  );

  delete window.optionSoundsMap[event.id];

});


function stopCurrentOptionSound() {
  if (window.currentOptionSoundInstance) {
    window.currentOptionSoundInstance.stop();

    window.currentOptionSoundInstance = null;
  }
}

function playOptionSound(questionId, optionIndex) {

  stopCurrentOptionSound();

  var soundId =
    "option_" +
    questionId +
    "_" +
    optionIndex;

  var soundData =
    window.optionSoundsMap[soundId];

  // الصوت مش موجود أو فشل
  if (!soundData) {

    console.warn(
      "🔇 No sound for option:",
      soundId
    );

    return;
  }

  // الصوت لسه بيتحمل
  if (!soundData.loaded) {

    console.warn(
      "⏳ Sound not ready:",
      soundId
    );

    return;
  }

  try {

    window.currentOptionSoundInstance =
      createjs.Sound.play(soundId);

  } catch (error) {

    console.warn(
      "⚠️ Sound play failed:",
      soundId,
      error.message
    );

    window.currentOptionSoundInstance = null;

  }

}

