function loadImageIntoBox(dragBox, path){
  const txt = dragBox.getChildByName("drag_txt");
  const dragShape = dragBox.drag1;
  const b = dragShape.nominalBounds 

  dragShape.removeAllChildren();

  if(path){
    const img = new Image();
    img.onload = function(){
      const bmp = new createjs.Bitmap(img);
      bmp.scaleX = b.width  / img.width;
      bmp.scaleY = b.height / img.height;

      bmp.x = 0;
      bmp.y = 0;

      dragShape.addChild(bmp);
      stage.update();
    };
    img.src = path;
  }
}

function loadLogoIntoMC(mc, url, forcedSize = { width: 250, height: 42 }) {
    if (!mc || !url) return;
    mc.removeAllChildren();
    var img = new Image();
    img.onload = function () {
        try {
            var pixelRatio = window.devicePixelRatio || 1;
            var off = document.createElement("canvas");
            off.width = forcedSize.width * pixelRatio;
            off.height = forcedSize.height * pixelRatio;
            var ctx = off.getContext("2d");
            ctx.imageSmoothingEnabled = true;
            ctx.imageSmoothingQuality = "high";
            ctx.drawImage(img, 0, 0, off.width, off.height);
            var bitmap = new createjs.Bitmap(off);
            bitmap.scaleX = forcedSize.width / off.width;
            bitmap.scaleY = forcedSize.height / off.height;
            bitmap.x = 0;
            bitmap.y = 0;
            mc.addChild(bitmap);
            stage.update();
        } catch (error) {
            console.warn(":warning: Failed to render logo.", error);
        }
    };
    img.onerror = function () {
        console.warn(":warning: Logo image failed to load:", url);
    };
    img.src = url;
}

function loadImageIntoMC(dragBox, path, type=""){

  if(!dragBox) return;
  const dragShape = dragBox.getChildAt(0);
  if(!dragShape) return;

  const b = dragShape.nominalBounds || {width:100, height:120};
  dragShape.removeAllChildren();

  if(path){
    // 1. Resolve target path format precisely
    var finalSrc = "";
    if(type == "logo"){
        finalSrc = logoURL;
    } else {
        finalSrc = templateDataURL ? templateDataURL + "/" + path : path;
    }

    // ⚡ 2. CACHE HIT: Check if this file is sitting loaded in our memory heap
    if (window.preloadedImagesCache[finalSrc]) {
        console.log("⚡ Instant Cache Render for URL: " + finalSrc);
        var cachedImg = window.preloadedImagesCache[finalSrc];
        var bmp = new createjs.Bitmap(cachedImg);

        bmp.scaleX = b.width / cachedImg.width;
        bmp.scaleY = b.height / cachedImg.height;
        bmp.x = 0;
        bmp.y = 0;

        dragShape.addChild(bmp);
        stage.update();
        return; // Break execution out completely!
    }

    // 3. CACHE MISS Fallback: Load manually if not ready yet
    console.log("⏳ Cache Miss. Loading file normally: " + finalSrc);
    const img = new Image();
    img.onload = function(){
      const bmp = new createjs.Bitmap(img);
      bmp.scaleX = b.width / img.width;
      bmp.scaleY = b.height / img.height;
      bmp.x = 0;
      bmp.y = 0;

      dragShape.addChild(bmp);
      stage.update();
    };
    img.src = finalSrc;
  }
}

//for scorm object 
window.interactions = [];

function addInteraction(id, type, response, result){

  const existing = window.interactions.find(i => i.id === id);

  if(existing){
    existing.response = response;
    existing.result = result;
  }else{
    window.interactions.push({
      id: id,
      type: type,
      response: response,
      result: result
    });
  }

}


function loadOptionImage(mc, path) {

    if (!mc || !path) return;

    var bounds = mc.nominalBounds || mc.getBounds();

    if (!bounds) {
        bounds = {
            width: mc.getTransformedBounds().width,
            height: mc.getTransformedBounds().height
        };
    }

    mc.removeAllChildren();

    // 1. توحيد المسار بنفس طريقة الكاش بالظبط (بإضافة علامة /)
    var finalSrc = templateDataURL ? templateDataURL + "/" + path : path;

    // 2. التحقق من الكاش أولاً قبل التحميل!
    if (window.preloadedImagesCache[finalSrc]) {
        console.log("⚡ Instant Cache Render for Option Image: " + finalSrc);
        var cachedImg = window.preloadedImagesCache[finalSrc];
        var bmp = new createjs.Bitmap(cachedImg);

        var scale = Math.max(
            bounds.width / cachedImg.width,
            bounds.height / cachedImg.height
        );

        bmp.scaleX = bmp.scaleY = scale;
        bmp.x = (bounds.width - cachedImg.width * scale) / 2;
        bmp.y = (bounds.height - cachedImg.height * scale) / 2;

        mc.addChild(bmp);
        stage.update();

        return; // 👈 الخروج فوراً عشان مانكملش تحميل من النت
    }

    // 3. لو الصورة مش موجودة في الكاش، حملها بالطريقة العادية
    var img = new Image();

    img.onload = function () {
        console.log("loaded from network/disk", img.src);
        var bmp = new createjs.Bitmap(img);

        // cover
        var scale = Math.max(
            bounds.width / img.width,
            bounds.height / img.height
        );

        bmp.scaleX = bmp.scaleY = scale;
        bmp.x = (bounds.width - img.width * scale) / 2;
        bmp.y = (bounds.height - img.height * scale) / 2;

        mc.addChild(bmp);
        stage.update();
    };

    img.onerror = function(){
        console.error("FAILED", img.src);
    };

    img.src = finalSrc;
}


/* =================================================
   GLOBAL IMAGE PRELOADER ENGINE (FIXED CACHE PATHS)
================================================= */
window.preloadedImagesCache = {}; 
window.isAssetsLoadingComplete = false;

window.preloadGameImages = function (jsonData, onCompleteCallback) {
    if (!jsonData || !jsonData.elements) {
        console.warn("⚠️ Preloader: Missing game elements array.");
        if (onCompleteCallback) onCompleteCallback();
        return;
    }

var imageUrls = [];

function addUrl(rawUrl) {
    if (!rawUrl || !rawUrl.trim()) return;
    rawUrl = rawUrl.trim();

    var resolvedUrl = window.templateDataURL ? window.templateDataURL + "/" + rawUrl : rawUrl;

    if (imageUrls.indexOf(resolvedUrl) === -1) {
        imageUrls.push(resolvedUrl);
    }
}

jsonData.elements.forEach(function (element) {
    // صورة السؤال
    if (element.question && element.question.img) {
        addUrl(element.question.img);
    }

    // صور الاختيارات
    if (element.options && element.options.length) {
        element.options.forEach(function (opt) {
            if (opt && opt.img) {
                addUrl(opt.img);
            }
        });
    }
});


    var totalImages = imageUrls.length;
    console.log("📦 Preloader: Found " + totalImages + " unique formatted images to cache.");

    if (totalImages === 0) {
        window.isAssetsLoadingComplete = true;
        if (onCompleteCallback) onCompleteCallback();
        return;
    }

    var loadedCount = 0;

    imageUrls.forEach(function (url) {
        // If already cached for some reason, skip download
        if (window.preloadedImagesCache[url]) {
            loadedCount++;
            if (loadedCount === totalImages) {
                window.isAssetsLoadingComplete = true;
                if (onCompleteCallback) onCompleteCallback();
            }
            return;
        }

        var imgAsset = new Image();

        imgAsset.onload = function () {
            loadedCount++;
            window.preloadedImagesCache[url] = imgAsset; // Store under the fully resolved path string
            console.log("✅ Cached [" + loadedCount + "/" + totalImages + "]: " + url);

            if (loadedCount === totalImages) {
                window.isAssetsLoadingComplete = true;
                console.log("🎉 All assets cached completely!");
                if (onCompleteCallback) onCompleteCallback();
            }
        };

        imgAsset.onerror = function () {
            loadedCount++;
            console.error("❌ Failed to preload target path: " + url);

            if (loadedCount === totalImages) {
                window.isAssetsLoadingComplete = true;
                if (onCompleteCallback) onCompleteCallback();
            }
        };

        imgAsset.src = url;
    });
};



// بتتنده من فريمات ten2..ten5 وآخر فريم جوه ten_frame_duplicate
window.checkAndReset = function (mc) {
  var isLastFrame = mc.currentFrame >= mc.totalFrames - 1;
  if (dotsNo != expectedCount && !isLastFrame) {
    return;
  }
  mc.stop();
  window.cancelTenHold(mc);

  // وقفة نص ثانية بعد آخر نقطة — بتتعد بفريمات الـ Ticker مش setTimeout
  var holdFrames = Math.round((createjs.Ticker.framerate || 24) * 0.5);
  mc._tenHoldListener = createjs.Ticker.on("tick", function () {
    holdFrames -= 1;
    if (holdFrames > 0) {
      return;
    }
    window.cancelTenHold(mc);
    mc.gotoAndStop(0);

    var done = window.onTenAnimDone;
    window.onTenAnimDone = null;
    if (done) {
      done(mc);
    }
  });
};

window.cancelTenHold = function (mc) {
  if (mc && mc._tenHoldListener) {
    createjs.Ticker.off("tick", mc._tenHoldListener);
    mc._tenHoldListener = null;
  }
};

function shake(target, intensity) {
	if (!target) {
		return;
	}
	intensity = intensity || 8;

	// خزّن المكان الأصلي أول مرة بس
	if (typeof target._shakeHomeX === "undefined") {
		target._shakeHomeX = target.x;
	}
	var originalX = target._shakeHomeX;

	createjs.Tween.removeTweens(target);
	target.x = originalX;   // رجّعه لمكانه قبل ما تبدأ
	createjs.Tween.get(target)
		.to({ x: originalX - intensity }, 45)
		.to({ x: originalX + intensity }, 90)
		.to({ x: originalX - Math.round(intensity * 0.6) }, 70)
		.to({ x: originalX + Math.round(intensity * 0.6) }, 70)
		.to({ x: originalX }, 45);
}
